accounts = {}
transactions = []
def open_acc(no, name):
    if no in accounts:
        print("이미 있는 계좌번호")
        return
    accounts[no] = {"이름": name, "잔액": 0}
    print(f"개설 완료: {name}")
def trade(kind, no, x):
    if no not in accounts:
        print("없는 계좌")
        return
    if x <= 0:
        print("금액 오류")
        return
    acc = accounts[no]
    if kind == "출금":
        if acc["잔액"] < x:
            print(f"잔액 부족 (잔액 {acc['잔액']}원)")
            return
        acc["잔액"] -= x
    else:
        acc["잔액"] += x
    transactions.append({"계좌": no, "종류": kind, "금액": x, "잔액": acc["잔액"]})
    print(f"{kind} 완료 (잔액 {acc['잔액']}원)")
def history(no):
    if no not in accounts:
        print("없는 계좌")
        return
    mine = [t for t in transactions if t["계좌"] == no]
    if not mine:
        print("거래 내역이 없습니다")
        return
    for i, t in enumerate(mine, 1):
        print(f"{i}. {t['종류']} {t['금액']}원 → {t['잔액']}원")
def stats():
    if not accounts:
        print("계좌가 없습니다")
        return
    total = sum(a["잔액"] for a in accounts.values())
    print(f"계좌 {len(accounts)}개, 총 잔액 {total}원, 평균 {total / len(accounts):.1f}원")
    best = max(accounts.values(), key=lambda a: a["잔액"])
    print(f"{best['이름']}({best['잔액']}원)")
while True:
    p = input().split()
    if p[0] == "종료":
        break
    if p[0] == "개설":
        open_acc(p[1], p[2])
    elif p[0] == "내역":
        history(p[1])
    elif p[0] == "통계":
        stats()
    else:
        trade(p[0], p[1], int(p[2]))

books = []
loans = {}
def find(title):
    for b in books:
        if b["제목"] == title:
            return b
    return None
def stock_in(title, author, n):
    b = find(title)
    if b:
        b["재고"] += n
        print(f"재입고: {title} (총 {b['재고']}권)")
    else:
        books.append({"제목": title, "저자": author, "재고": n})
        print(f"신규 등록: {title}")
def borrow(who, title):
    b = find(title)
    if b is None:
        print("없는 도서")
    elif b["재고"] == 0:
        print("대출 불가")
    elif title in loans.get(who, []):
        print("중복 대출")
    else:
        b["재고"] -= 1
        if who not in loans:
            loans[who] = []
        loans[who].append(title)
        print("대출 완료")
def give_back(who, title):
    if title not in loans.get(who, []):
        print("반납 오류")
        return
    loans[who].remove(title)
    find(title)["재고"] += 1
    print("반납 완료")
def search(key):
    key = key.lower()
    hit = [b for b in books if key in b["제목"].lower() or key in b["저자"].lower()]
    if not hit:
        print("검색 결과 없음")
    for b in hit:
        print(f"{b['제목']}/{b['저자']}/{b['재고']}")
def status():
    active = sorted(w for w in loans if loans[w])
    if not active:
        print("대출 중인 도서 없음")
    for w in active:
        print(f"{w}: {', '.join(loans[w])}")
    print(f"총 재고 {sum(b['재고'] for b in books)}권")
while True:
    p = input().split()
    if p[0] == "종료":
        break
    if p[0] == "입고":
        stock_in(p[1], p[2], int(p[3]))
    elif p[0] == "대출":
        borrow(p[1], p[2])
    elif p[0] == "반납":
        give_back(p[1], p[2])
    elif p[0] == "검색":
        search(p[1])
    else:
        status()

