items = {}
loans = {}
def register(name, n):
    if name in items:
        items[name]["전체"] += n
        items[name]["남은"] += n
        print(f"추가 등록: {name} (총 {items[name]['전체']}개)")
    else:
        items[name] = {"전체": n, "남은": n}
        print(f"신규 등록: {name}")
def rent(who, name, n):
    if name not in items:
        print("없는 물품")
    elif n < 1:
        print("수량 오류")
    elif items[name]["남은"] < n:
        print(f"재고 부족 (남은 {items[name]['남은']}개)")
    elif len(loans.get(who, {})) >= 3 and name not in loans[who]:
        print("대여 한도 초과")
    else:
        items[name]["남은"] -= n
        if who not in loans:
            loans[who] = {}
        loans[who][name] = loans[who].get(name, 0) + n
        print("대여 완료")
def give_back(who, name, n):
    if n < 1 or loans.get(who, {}).get(name, 0) < n:
        print("반납 오류")
        return
    loans[who][name] -= n
    if loans[who][name] == 0:
        del loans[who][name]
    items[name]["남은"] += n
    print("반납 완료")
def lookup(who):
    mine = loans.get(who, {})
    if mine:
        print(" ".join(f"{k}×{mine[k]}" for k in sorted(mine)))
    else:
        print("대여 내역 없음")
def stats():
    if not items:
        print("등록된 물품 없음")
        return
    best = None
    for k in items:
        print(f"{k} {items[k]['남은']}/{items[k]['전체']}")
        out = items[k]["전체"] - items[k]["남은"]
        if out > 0 and (best is None or out > items[best]["전체"] - items[best]["남은"]):
            best = k
    if best is None:
        print("대여 중인 물품 없음")
    else:
        print(best)
while True:
    p = input().split()
    if p[0] == "종료":
        break
    if p[0] == "등록":
        register(p[1], int(p[2]))
    elif p[0] == "대여":
        rent(p[1], p[2], int(p[3]))
    elif p[0] == "반납":
        give_back(p[1], p[2], int(p[3]))
    elif p[0] == "조회":
        lookup(p[1])
    else:
        stats()
